head.script:
scwin.inputVal = function(test) {
    return false;
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq('#wq_uuid_2').val() == '12,345.22';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");    
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_2').setValue('12345.222')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_2').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_2').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    //Function 
